    print('demo',n)
    for c in comps(gi,8):
        s=set(c)
        rs=[i for i,_ in c]; cs_=[j for _,j in c]
        # is it a full 2x2 square?
        isSq = len(c)==4 and max(rs)-min(rs)+1==2 and max(cs_)-min(cs_)+1==2
        # L triomino: 2x2 box minus one cell
        box=max(rs)-min(rs)+1
        triom = len(c)==3 and box==2 and len(s)==3
        elbs=[]
        if triom:
            boxset={(min(rs)+di,min(cs_)+dj) for di in(0,1) for dj in(0,1)}
            miss=list(boxset-s)[0]
            ei, ej = miss[0], miss[1]
            elbs.append(('elbow',ei-min(rs),ej-min(cs_),tuple(sorted(c))))
        feat=('square' if isSq else ('trio'+str(len(elbs))),'color',go[c[0][0]][c[0][1]])
        print(feat, 'cells',sorted(c))

