                col=COL[tag]
                for p in ins: o[p[0]][p[1]]=col
        res.append(o)
    return res,sols,blob,P
for n in (1,2,3):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    res,sols,blob,P=solve_all(gi)
    ok=[bool(r==go) for r in res]
    print(n,'numcovers',len(sols),'matching:',ok)
